#!/bin/sh
# Prints the PKGBUILD of the `rxh-bin` AUR package of a release, which
# installs the static musl archives published by .github/workflows/release.yml.
#
# Usage: pkgbuild.sh VERSION SHA256SUMS
#
# SHA256SUMS is the checksum file of the release (`sha256sum` format) with
# the x86_64 and aarch64 `rxh-VERSION-ARCH-unknown-linux-musl.tar.gz`.
set -eu

if [ "$#" -ne 2 ]; then
    echo "usage: $0 VERSION SHA256SUMS" >&2
    exit 2
fi
version=$1
sums=$2
dist=$(dirname "$0")

. "$dist/release-lib.sh"
check_version "$version"
# AUR versions cannot hold `-`: 1.0.0-rc.1 becomes 1.0.0rc.1, which pacman
# sorts before 1.0.0.
pkgver=$(echo "$version" | tr -d -)
x86_64=$(checksum "$sums" "rxh-$version-x86_64-unknown-linux-musl.tar.gz")
aarch64=$(checksum "$sums" "rxh-$version-aarch64-unknown-linux-musl.tar.gz")

cat <<PKGBUILD
# Maintainer: LOSEARDES77 <https://github.com/LOSEARDES77>
# Generated by dist/pkgbuild.sh for release $version.
pkgname=rxh-bin
pkgver=$pkgver
pkgrel=1
pkgdesc='Reverse proxy and layer 4 load balancer with live upstream management'
arch=('x86_64' 'aarch64')
url='$repository'
license=('MIT')
provides=('rxh')
conflicts=('rxh')
backup=('etc/rxh/rxh.toml')
options=('!strip' '!debug')
source_x86_64=("$repository/releases/download/v$version/rxh-$version-x86_64-unknown-linux-musl.tar.gz")
source_aarch64=("$repository/releases/download/v$version/rxh-$version-aarch64-unknown-linux-musl.tar.gz")
sha256sums_x86_64=('$x86_64')
sha256sums_aarch64=('$aarch64')

package() {
  cd "rxh-$version-\$CARCH-unknown-linux-musl"
  install -Dm755 rxh "\$pkgdir/usr/bin/rxh"
  install -Dm644 rxh.toml "\$pkgdir/etc/rxh/rxh.toml"
  install -Dm644 systemd/rxh.service "\$pkgdir/usr/lib/systemd/system/rxh.service"
  install -Dm644 systemd/rxh.socket "\$pkgdir/usr/lib/systemd/system/rxh.socket"
  install -Dm644 systemd/rxh.sysusers "\$pkgdir/usr/lib/sysusers.d/rxh.conf"
  install -Dm644 -t "\$pkgdir/usr/share/man/man1" man/*.1
  install -Dm644 completions/rxh.bash "\$pkgdir/usr/share/bash-completion/completions/rxh"
  install -Dm644 completions/_rxh "\$pkgdir/usr/share/zsh/site-functions/_rxh"
  install -Dm644 completions/rxh.fish "\$pkgdir/usr/share/fish/vendor_completions.d/rxh.fish"
  install -Dm644 LICENSE "\$pkgdir/usr/share/licenses/rxh-bin/LICENSE"
}
PKGBUILD
